// Build ICSE 9 Mathematics ch11 Rectilinear Figures: Parallelograms. Run from platform/:
//   npx tsx content/authored/maths/icse-9-mathematics-ch11/src/build.mjs
// Every figure is built from coordinates (geo.mjs, figs.mjs); every length, angle, parallel and equal-length claim on a slide, in a
// table or in a note is computed from those coordinates and asserted here, and every number in the narration is produced by number
// words from the computed value. The build throws if anything disagrees.
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, table, flow, build, chapterTests, r } from './lib.mjs';
import * as G from './geo.mjs';
import * as F from './figs.mjs';

setUnit('icse-9-mathematics-ch11', { author: 'claude-sonnet-5-5 (writer; reviewed by the subject-producer)' });
await import('./questions.mjs');
await import('./questions2.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const { near, dist, must, angDeg, ang, interior, perimeter, area, paraSA } = G;
const { nw } = F;
const d = (s) => `$${s}$`;
const V = (p) => [p.A, p.B, p.C, p.D];

// ---------------------------------------------------------------- facts verified for the slides
// Main parallelogram: AB = 8, AD = 4.5, angle A = angle C = 62, angle B = angle D = 118.
must(near(F.P.ab, 8) && near(F.P.ad, 4.5) && near(F.P.angA, 62) && near(F.P.angB, 118) && near(interior(V(F.P), 2), 62) && near(interior(V(F.P), 3), 118), 'main parallelogram');
// Example 1: angle P = 64: angle Q = angle S = 116, angle R = 64.
must(near(F.E1.angA, 64) && near(F.E1.angB, 116) && near(interior(V(F.E1), 2), 64) && near(interior(V(F.E1), 3), 116), 'e1');
// Example 2: angle A = (3x + 10), angle B = (2x + 30): 5x + 40 = 180, x = 28, A = 94, B = 86.
const x2 = 28; const E2 = paraSA(7, 4.2, 94);
must(5 * x2 + 40 === 180 && 3 * x2 + 10 === 94 && 2 * x2 + 30 === 86 && near(E2.angA, 94) && near(E2.angB, 86) && near(E2.angA + E2.angB, 180), 'e2');
// Example 3: AB = (2x + 3) = DC = (5x - 12): x = 5, AB = 13, AD = 8, perimeter 42.
const x3 = 5;
must(2 * x3 + 3 === 5 * x3 - 12 && near(F.E3.ab, 13) && near(F.E3.ad, 8) && near(F.E3.per, 42) && near(dist(F.E3.C, F.E3.D), 5 * x3 - 12), 'e3');
// Example 4: OA = (3x - 1) = OC = (x + 9): x = 5, OA = 14, AC = 28, BD = 22, OB = 11.
const x4 = 5;
must(3 * x4 - 1 === x4 + 9 && near(dist(F.E4.A, F.E4.O), 14) && near(F.E4.ac, 28) && near(F.E4.bd, 22) && near(dist(F.E4.B, F.E4.O), 11), 'e4');
// Example 5: AB = 9, AC = 14, BD = 11: OA = 7, OB = 5.5, perimeter of triangle AOB = 21.5.
must(near(F.E5.ab, 9) && near(dist(F.E5.A, F.E5.O), 7) && near(dist(F.E5.B, F.E5.O), 5.5) && near(perimeter(F.E5.A, F.E5.O, F.E5.B), 21.5), 'e5');
// Four triangles at O of the main parallelogram have equal area; each diagonal halves the area (props asserts it too).
must([area(F.P.A, F.P.O, F.P.B), area(F.P.B, F.P.O, F.P.C), area(F.P.C, F.P.O, F.P.D), area(F.P.D, F.P.O, F.P.A)].every((v) => near(v, F.P.area / 4)), 'four equal areas');
// Rhombus 16 and 12: side 10; rhombus 14 and 48: side 25, perimeter 100.
must(near(F.RH.side, 20) && near(F.RH.ac, 32) && near(F.RH.bd, 24) && near(F.RH2.side, 25) && near(F.RH2.per, 100) && near(F.RH2.ac, 48) && near(F.RH2.bd, 14), 'rhombus numbers');
// Rhombus with angle A = 76: angle B = 104, angle BAC = 38, angle ABD = 52.
must(near(F.RH3.angA, 76) && near(F.RH3.angB, 104) && near(ang(F.RH3.B, F.RH3.A, F.RH3.C), 38) && near(ang(F.RH3.A, F.RH3.B, F.RH3.D), 52), 'rhombus angles');
// Rectangle 24 by 10: diagonal 26, OA = 13, perimeter of triangle AOB = 50.
must(near(F.RE.ab, 24) && near(F.RE.ad, 10) && near(F.RE.ac, 26) && near(dist(F.RE.O, F.RE.A), 13) && near(perimeter(F.RE.A, F.RE.O, F.RE.B), 50) && near(26 * 26 - 24 * 24, 10 * 10), 'rectangle');
// Rectangle with angle ADB = 28: angle ABD = 62, angle AOB = 56.
must(near(ang(F.RE2.A, F.RE2.D, F.RE2.B), 28) && near(ang(F.RE2.A, F.RE2.B, F.RE2.D), 62) && near(angDeg(F.RE2.O, F.RE2.A, F.RE2.B), 56) && near(dist(F.RE2.O, F.RE2.A), dist(F.RE2.O, F.RE2.B)), 'rectangle angles');
// Square with diagonal 18: area 162; the unit square has diagonal angles 45.
must(near(F.SQ2.ac, 18) && near(F.SQ2.area, 162) && near(ang(F.SQ.B, F.SQ.A, F.SQ.C), 45), 'square');
// Mixed example: perpendicular diagonals, AB = 13, AC = 24: OA = 12, OB = 5, BD = 10, perimeter 52, area 120.
must(near(F.RH4.side, 13) && near(F.RH4.ac, 24) && near(F.RH4.bd, 10) && near(F.RH4.per, 52) && near(F.RH4.area, 120) && near(13 * 13 - 12 * 12, 5 * 5), 'mixed');

// ---------------------------------------------------------------- tables
const tbl = (h, rows, alt) => table(h, rows, alt);
const angleRowsT = tbl(['Pair of angles', 'Relation', 'Reason'], [['Opposite, such as A and C', 'equal', 'proved on the next slides'], ['Neighbouring, such as A and B', 'add up to 180 degrees', 'co-interior angles between parallel sides'], ['All four', 'add up to 360 degrees', 'angle sum of a quadrilateral']], 'Table of the angle facts of a parallelogram: opposite angles are equal, neighbouring angles add up to one hundred eighty degrees and all four angles add up to three hundred sixty degrees.');
const oppProofT = tbl(['Claim', 'Reason'], [[d(r`\angle A + \angle B = 180^\circ`), '$AD \\parallel BC$, transversal $AB$: co-interior angles'], [d(r`\angle B + \angle C = 180^\circ`), '$AB \\parallel DC$, transversal $BC$: co-interior angles'], [d(r`\angle A = \angle C`), 'both equal $180^\\circ - \\angle B$'], [d(r`\angle B = \angle D`), 'the same argument with $\\angle C + \\angle D = 180^\\circ$']], 'Table of four claims and reasons proving that the opposite angles of a parallelogram are equal, using two pairs of co-interior angles.');
const ex2T = tbl(['Step', 'Working'], [['Neighbouring angles', d(r`(3x + 10) + (2x + 30) = 180`)], ['Collect', d(r`5x + 40 = 180`)], ['Solve', d(r`x = 28`)], ['The angles', d(r`\angle A = 94^\circ, \ \angle B = 86^\circ`)], ['Check', d(r`94 + 86 = 180`)]], 'Table of five steps: the neighbouring angles three x plus ten and two x plus thirty add up to one hundred eighty, so x is twenty eight, angle A is ninety four and angle B is eighty six degrees.');
const onePairProofT = tbl(['Claim', 'Reason'], [[d('AB = CD'), 'given'], [d(r`\angle BAC = \angle DCA`), 'alternate angles, $AB \\parallel DC$'], [r`$\triangle ABC \cong \triangle CDA$`, '$AC$ common: side angle side'], [d(r`\angle B = \angle D`), 'corresponding parts'], [d(r`\angle BCA = \angle DAC`), 'corresponding parts: alternate angles, so $AD \\parallel BC$'], [d(r`\angle A = \angle C`), '$\\angle BAC + \\angle CAD = \\angle DCA + \\angle ACB$']], 'Table of six claims and reasons for a quadrilateral with one pair of opposite sides equal and parallel: join the diagonal, prove the two triangles congruent, and add the angles at A and C to get angle A equal to angle C.');
const diagProofT = tbl(['Claim', 'Reason'], [[d('AB = CD'), 'opposite sides of the parallelogram'], [d(r`\angle OAB = \angle OCD`), 'alternate angles, $AB \\parallel DC$, transversal $AC$'], [d(r`\angle OBA = \angle ODC`), 'alternate angles, transversal $BD$'], [r`$\triangle AOB \cong \triangle COD$`, 'angle side angle'], [d('OA = OC, \\ OB = OD'), 'corresponding parts']], 'Table of five claims and reasons proving that the diagonals of a parallelogram bisect each other, by the congruent triangles A O B and C O D.');
const ex5pT = tbl(['Side of triangle AOB', 'Reason', 'Length'], [['AB', 'given', d(r`9`)], ['OA', 'half of $AC = 14$', d(r`7`)], ['OB', 'half of $BD = 11$', d(r`5.5`)], ['Perimeter', 'sum', d(r`21.5`)]], 'Table for triangle A O B in a parallelogram with A B nine, A C fourteen and B D eleven: O A is seven, O B is five point five and the perimeter is twenty one point five.');
const sum1T = tbl(['Idea', 'Rule'], [['Opposite sides', 'equal and parallel'], ['Opposite angles', d(r`\angle A = \angle C, \ \angle B = \angle D`)], ['Neighbouring angles', d(r`\angle A + \angle B = 180^\circ`)], ['One equal parallel pair', 'also gives a parallelogram; opposite angles equal'], ['Diagonals', 'bisect each other; each cuts it into two congruent triangles']], 'Summary table of part one: opposite sides, opposite angles, neighbouring angles, one equal and parallel pair, and the diagonals of a parallelogram.');
const tips1T = tbl(['Slip', 'Correct'], [[d(r`\angle A = \angle B`), d(r`\angle A = \angle C, \ \angle A + \angle B = 180^\circ`)], ['diagonals equal in every parallelogram', 'the diagonals bisect each other; they are equal only in a rectangle'], ['no reason beside a step', 'write the reason: alternate, co-interior, opposite sides'], [d(r`\triangle ABC \cong \triangle CDA`) + ' written without naming the condition', 'say angle side angle or side angle side']], 'Table of four common slips of part one and their corrections: neighbouring angles add to one hundred eighty, the diagonals are equal only in a rectangle, every step needs a reason, and the congruence condition must be named.');
const rhProofT = tbl(['Claim', 'Reason'], [[d('OB = OD'), 'diagonals of a parallelogram bisect each other'], [d('AB = AD'), 'sides of a rhombus'], [d('AO = AO'), 'common side'], [r`$\triangle AOB \cong \triangle AOD$`, 'side side side'], [d(r`\angle AOB = \angle AOD`), 'corresponding parts'], [d(r`\angle AOB + \angle AOD = 180^\circ`), 'angles on the straight line $BD$'], [d(r`\angle AOB = \angle AOD = 90^\circ`), 'equal angles adding up to 180']], 'Table of seven claims and reasons proving that the diagonals of a rhombus meet at right angles, by the congruent triangles A O B and A O D.');
const ex1T = tbl(['Step', 'Working'], [['Diagonals bisect at right angles', d(r`OA = 24, \ OB = 7`)], ['Right triangle AOB', d(r`AB^2 = 24^2 + 7^2 = 625`)], ['Side', d(r`AB = 25 \text{ cm}`)], ['Perimeter', d(r`4 \times 25 = 100 \text{ cm}`)]], 'Table of four steps for a rhombus with diagonals forty eight and fourteen centimetres: the half-diagonals are twenty four and seven, the side is twenty five and the perimeter is one hundred centimetres.');
const reProofT = tbl(['Claim', 'Reason'], [[d('AB = DC'), 'opposite sides of the rectangle'], [d(r`\angle ABC = \angle DCB = 90^\circ`), 'corners of the rectangle'], [d('BC = CB'), 'common side'], [r`$\triangle ABC \cong \triangle DCB$`, 'side angle side'], [d('AC = DB'), 'corresponding parts']], 'Table of five claims and reasons proving that the diagonals of a rectangle are equal, by the congruent triangles A B C and D C B.');
const sqT = tbl(['Property of a square', 'Why'], [['Four equal sides', 'it is a rhombus'], ['Four right angles', 'it is a rectangle'], ['Diagonals equal', 'it is a rectangle'], ['Diagonals meet at right angles', 'it is a rhombus'], ['Diagonals bisect each other and the corners', 'it is a parallelogram and a rhombus: 45 degrees each']], 'Table of the properties of a square and the family it comes from: four equal sides and perpendicular diagonals from the rhombus, right angles and equal diagonals from the rectangle.');
const familyT = tbl(['Property', 'Parallelogram', 'Rhombus', 'Rectangle', 'Square'], [['Opposite sides equal and parallel', 'yes', 'yes', 'yes', 'yes'], ['Diagonals bisect each other', 'yes', 'yes', 'yes', 'yes'], ['Diagonals equal', 'no', 'no', 'yes', 'yes'], ['Diagonals at right angles', 'no', 'yes', 'no', 'yes'], ['Four equal sides', 'no', 'yes', 'no', 'yes'], ['Four right angles', 'no', 'no', 'yes', 'yes']], 'Table comparing the parallelogram, rhombus, rectangle and square on six properties. Only the square has all of them.');
const identT = tbl(['Parallelogram whose diagonals are', 'It is a', 'Reason'], [['at right angles', 'rhombus', 'four equal sides, as in the proof of this part'], ['equal', 'rectangle', 'four right angles'], ['equal and at right angles', 'square', 'both']], 'Table of three cases: a parallelogram with perpendicular diagonals is a rhombus, with equal diagonals a rectangle, and with both a square.');
const sum2T = tbl(['Shape', 'Diagonal facts'], [['Rhombus', 'bisect each other at right angles and bisect the corner angles'], ['Rectangle', 'equal, so OA = OB = OC = OD'], ['Square', 'equal, at right angles, 45 degrees to the sides'], ['Any of them', 'also a parallelogram: diagonals bisect each other']], 'Summary table of part two: the diagonal facts of the rhombus, the rectangle and the square.');
const tips2T = tbl(['Slip', 'Correct'], [['diagonals of a rhombus are equal', 'they are perpendicular; equal only in a square'], ['diagonals of a rectangle meet at right angles', 'they are equal; perpendicular only in a square'], ['using the whole diagonal as a leg', 'the right triangle has the half-diagonals as legs'], ['rhombus area written without the four triangles', 'four triangles of half-diagonals, or work out each triangle first']], 'Table of four common slips of part two and their corrections: the diagonals of a rhombus are perpendicular, those of a rectangle are equal, use half-diagonals as legs, and count four triangles.');

// ---------------------------------------------------------------- flow
const fam = F.flowFamily();
const flowFamily = flow('LR', fam.nodes, fam.edges, 'Flow of four boxes: a parallelogram becomes a rhombus when all four sides are equal, and a rectangle when one angle is a right angle. A rhombus with a right angle, or a rectangle with equal sides, is a square.', 'The special parallelograms');
const flowSolve = flow('LR', [['a', 'Draw the figure and mark what is given'], ['b', 'Name the family: parallelogram, rhombus, rectangle, square'], ['c', 'List its diagonal and angle facts'], ['d', 'Use a triangle at O and write reasons']], [['a', 'b', 'then'], ['b', 'c', 'then'], ['c', 'd', 'then']], 'Flow with four boxes: draw the figure, name the family, list the diagonal and angle facts, then use a triangle at O and write the reasons.', 'A routine for problems');

// ---------------------------------------------------------------- deck 1
const d1 = deck({
  part: 1,
  title: 'Rectilinear Figures: Parallelograms — Part 1: Sides, angles and diagonals',
  goals: ['Use the equal opposite sides and angles and the 180 degree rule of a parallelogram', 'Prove that the opposite angles of a parallelogram are equal, also from one equal and parallel pair of sides', 'Prove that the diagonals bisect each other and cut the parallelogram into two congruent triangles', 'Use these facts to find unknown sides, angles and lengths'],
  slides: [
    sl('title', 'Parallelograms, Part 1', { b: 'A **parallelogram** has both pairs of opposite sides **parallel**. In this part we find what that forces: equal sides, equal angles and **diagonals that bisect each other**.', v: F.figParT(), n: 'Welcome. A parallelogram is a four sided figure with both pairs of opposite sides parallel. That one idea forces a lot. Opposite sides are equal, opposite angles are equal, and the diagonals cut each other in half. In this part we prove the important results and use them to find unknown angles and lengths.' }),
    sl('concept', 'What is a parallelogram?', { b: 'A quadrilateral $ABCD$ is a **parallelogram** when $AB \\parallel DC$ and $AD \\parallel BC$.\n\nThe arrows in the figure mark the two parallel pairs.', v: F.figPar(), n: 'A quadrilateral is a parallelogram when both pairs of opposite sides are parallel. In the figure the single arrows mark the pair A B and D C, and the double arrows mark the pair A D and B C. This is the definition. Everything else in this chapter is a consequence of it.' }),
    sl('concept', 'Sides of a parallelogram', { b: 'The **opposite sides are equal**: $AB = DC$ and $AD = BC$.\n\nIn the figure $AB = DC = 8$ cm and $AD = BC = 4.5$ cm, so the perimeter is $2(8 + 4.5) = 25$ cm.\n\n*The proof that both pairs of opposite sides are equal is not in the ICSE 2028 Class IX syllabus; we use the result.*', v: F.figParLen(), n: `The opposite sides of a parallelogram are equal. In the figure A B and D C are each ${nw(F.P.ab)} centimetres, and A D and B C are each ${nw(F.P.ad)} centimetres. So the perimeter is two times ${nw(F.P.ab)} plus ${nw(F.P.ad)}, which is ${nw(F.P.per)} centimetres. The proof of this result is not required in the syllabus, so we simply use it.` }),
    sl('concept', 'Angles: neighbours add up to 180 degrees', { b: 'Since $AD \\parallel BC$, the angles $\\angle A$ and $\\angle B$ are **co-interior angles** on the transversal $AB$, so $\\angle A + \\angle B = 180^\\circ$.', v: angleRowsT, n: `Look at the angles at A and B. The sides A D and B C are parallel, and A B cuts across them. So the angles at A and B are co-interior angles, and they add up to one hundred eighty degrees. In the figure with angle A equal to ${nw(F.P.angA)}, angle B is ${nw(F.P.angB)}. Every pair of neighbouring angles in a parallelogram adds up to one hundred eighty degrees.` }),
    sl('concept', 'Theorem: opposite angles are equal', { b: '**Theorem.** The opposite angles of a parallelogram are equal.\n\nIn parallelogram $ABCD$: $\\angle A = \\angle C$ and $\\angle B = \\angle D$.', v: F.figAng(), n: `Here is the theorem. In a parallelogram the opposite angles are equal. In the figure angle A and angle C are both ${nw(62)} degrees, shown with one arc, and angle B and angle D are both ${nw(118)} degrees, shown with two arcs. Notice that ${nw(62)} plus ${nw(118)} is one hundred eighty, as neighbouring angles must be. Now we prove it.` }),
    sl('concept', 'Proof that opposite angles are equal', { b: 'Use the co-interior angles twice. Both pairs of sides are parallel, so both give a sum of $180^\\circ$.', v: oppProofT, n: 'The proof uses co-interior angles twice. A D is parallel to B C, with transversal A B, so angle A plus angle B is one hundred eighty degrees. A B is parallel to D C, with transversal B C, so angle B plus angle C is one hundred eighty degrees. Both sums equal one hundred eighty, so angle A equals angle C. The same argument gives angle B equal to angle D.' }),
    sl('check', 'Quick check: which angles are equal?', { b: 'Pick the pair that must be equal in every parallelogram.', chk: 'm01', v: F.figAngSym(), n: 'In a parallelogram A B C D, which pair of angles must be equal? Use the figure. The angles marked with one arc are equal, and the angle marked with two arcs is the supplement. Choose the pair that is equal in every parallelogram, not just in special ones.' }),
    sl('example', 'Worked example 1: all the angles', { b: 'In parallelogram $PQRS$, $\\angle P = 64^\\circ$. Find $a = \\angle Q$, $b = \\angle R$ and $c = \\angle S$.', ul: ["**Step 1 —** $\\angle Q = 180^\\circ - 64^\\circ = 116^\\circ$ (neighbouring angles).","**Step 2 —** $\\angle R = \\angle P = 64^\\circ$ and $\\angle S = \\angle Q = 116^\\circ$ (opposite angles).","**Answer —** $a = 116^\\circ$, $b = 64^\\circ$, $c = 116^\\circ$."], v: F.figE1(), n: `The angle at Q is next to the angle at P, so they add to one hundred eighty. Angle Q is ${nw(F.E1.angB)} degrees. The angle at R is opposite the angle at P, so it is ${nw(F.E1.angA)} degrees. The angle at S is opposite the angle at Q, so it is ${nw(F.E1.angB)} degrees. As a check, the four angles add up to ${nw(2 * F.E1.angA + 2 * F.E1.angB)} degrees.` }),
    sl('example', 'Worked example 2: angles with x', { b: 'In parallelogram $ABCD$, $\\angle A = (3x + 10)^\\circ$ and $\\angle B = (2x + 30)^\\circ$. Find $x$ and the angles.', v: ex2T, n: `The angles A and B are neighbours, so they add to one hundred eighty. Three x plus ten plus two x plus thirty equals one hundred eighty, which gives five x plus forty equals one hundred eighty. So x is ${nw(x2)}. Then angle A is ${nw(94)} degrees and angle B is ${nw(86)} degrees. Check that they add to one hundred eighty.` }),
    sl('example', 'Worked example 3: sides with x', { b: 'In parallelogram $ABCD$, $AB = (2x + 3)$ cm, $DC = (5x - 12)$ cm and $AD = 8$ cm. Find $x$, $AB$ and the perimeter.', ul: ["**Step 1 —** $AB = DC$, so $2x + 3 = 5x - 12$ and $x = 5$.","**Step 2 —** $AB = 2(5) + 3 = 13$ cm.","**Answer —** perimeter $= 2(13 + 8) = 42$ cm."], v: F.figE3(), n: `The opposite sides A B and D C are equal. So two x plus three equals five x minus twelve. That gives three x equals fifteen, and x is ${nw(x3)}. Then A B is ${nw(13)} centimetres. The sides A D and B C are ${nw(8)} each, so the perimeter is two times ${nw(13)} plus ${nw(8)}, which is ${nw(42)} centimetres.` }),
    sl('concept', 'One pair equal and parallel', { b: 'If $AB \\parallel DC$ and $AB = DC$ in a quadrilateral $ABCD$, then $ABCD$ is a **parallelogram**.\n\n*The proof of this test is not in the ICSE 2028 Class IX syllabus; we use it, and we prove the angle result that follows.*', v: F.figOne(false), n: 'Sometimes we are told less. Suppose in a quadrilateral A B C D, the side A B is parallel and equal to D C. Then A B C D is a parallelogram. The proof of this test is not part of the syllabus, so we use it. What the syllabus does ask is the next result: proving that the opposite angles are equal from this one pair.' }),
    sl('concept', 'Opposite angles from one equal parallel pair', { b: 'Join $AC$. The shaded triangles $ABC$ and $CDA$ have $AB = CD$, $AC$ in common, and equal alternate angles $\\angle BAC = \\angle DCA$.', v: onePairProofT, n: 'Join A to C. The triangles A B C and C D A match. A B equals C D, given. The angles B A C and D C A are alternate angles between the parallel lines, so they are equal. And A C is common. Two sides and the angle between them agree, so the triangles are congruent. Then angle B equals angle D. Adding the two parts at A and at C gives angle A equal to angle C.' }),
    sl('concept', 'The proof in the figure', { b: 'The alternate angles marked $p$ are equal because $AB \\parallel DC$. The congruent triangles are shaded.', v: F.figOne(true), n: 'In the figure the diagonal A C is dashed and the two triangles are shaded. The angles marked p are the alternate angles, equal because A B is parallel to D C. Once the triangles are congruent, the angles marked at B and at D are equal, and the angles of the triangles at A and at C add together to give equal angles A and C.' }),
    sl('check', 'Quick check: neighbouring angles', { b: 'Decide whether Neha\'s report is possible.', chk: 'tf1', v: angleRowsT, n: 'Neha measures a parallelogram shaped ring frame and reports two neighbouring angles of seventy degrees and one hundred degrees. Is her report possible? Remember the rule for neighbouring angles of a parallelogram, and add the two numbers.' }),
    sl('concept', 'Diagonals bisect each other', { b: '**Theorem.** The diagonals of a parallelogram **bisect each other**: $OA = OC$ and $OB = OD$.', v: F.figDiag(), n: `The diagonals of a parallelogram cross at a point O. The theorem says that O is the mid-point of both diagonals. The tick marks show that O A equals O C, and O B equals O D. In a parallelogram with A C equal to ${nw(F.P.ac)} and B D equal to ${nw(F.P.bd)}, the half lengths are ${nw(dist(F.P.A, F.P.O))} and ${nw(dist(F.P.B, F.P.O))}. Now the proof.` }),
    sl('concept', 'Proof: the diagonals bisect each other', { b: 'Compare the shaded triangles $AOB$ and $COD$.', v: diagProofT, n: 'Compare the triangles A O B and C O D. A B equals C D, as opposite sides. The angles O A B and O C D are alternate angles, because A B is parallel to D C, so they are equal. The angles O B A and O D C are also alternate angles, so they are equal. Two angles and the included side agree, so the triangles are congruent. Hence O A equals O C and O B equals O D.' }),
    sl('concept', 'A diagonal makes two congruent triangles', { b: 'The diagonal $AC$ cuts the parallelogram into $\\triangle ABC$ and $\\triangle CDA$. They are **congruent**, so they have **equal areas**: each is half of the parallelogram.', v: F.figCong(), n: `A diagonal cuts a parallelogram into two triangles. In the figure the triangles A B C and C D A are shaded. They share the diagonal A C, and the alternate angles at A and at C are equal. So the triangles are congruent. Congruent triangles have equal area, so each is half of the parallelogram. And the two diagonals together make four triangles at O, each with area one quarter, here ${nw(G.r6(F.P.area / 4))}.` }),
    sl('example', 'Worked example 4: the diagonals with x', { b: 'The diagonals of parallelogram $ABCD$ meet at $O$, with $OA = (3x - 1)$ cm, $OC = (x + 9)$ cm and $BD = 22$ cm. Find $x$, $AC$ and $OB$.', ul: ["**Step 1 —** $OA = OC$, so $3x - 1 = x + 9$ and $x = 5$.","**Step 2 —** $OA = OC = 14$ cm, so $AC = 28$ cm.","**Answer —** $OB = \\dfrac{1}{2} \\times 22 = 11$ cm."], v: F.figE4(), n: `The diagonals bisect each other, so O A equals O C. Three x minus one equals x plus nine, which gives two x equals ten, and x is ${nw(x4)}. Then O A and O C are ${nw(14)} each, and A C is ${nw(28)} centimetres. For the other diagonal, B D is ${nw(22)}, and O is its mid-point, so O B is ${nw(11)} centimetres.` }),
    sl('check', 'Quick check: a ratio of angles', { b: 'Use the angle sum for neighbouring angles.', chk: 'n1', v: F.figAng(), n: 'The neighbouring angles of a parallelogram shaped dance floor are in the ratio seven to five. Find the smaller angle. Think about what the two angles add up to, then split that total in the given ratio.' }),
    sl('example', 'Worked example 5: a triangle at the centre', { b: 'In parallelogram $ABCD$, $AB = 9$ cm, $AC = 14$ cm and $BD = 11$ cm. Find the perimeter of $\\triangle AOB$.', v: ex5pT, n: `The sides of triangle A O B are A B, O A and O B. A B is ${nw(9)} centimetres. The diagonals bisect each other, so O A is half of ${nw(14)}, which is ${nw(7)}, and O B is half of ${nw(11)}, which is ${nw(5.5)}. The perimeter is ${nw(9)} plus ${nw(7)} plus ${nw(5.5)}, which is ${nw(21.5)} centimetres. Notice that we never needed the other sides.` }),
    sl('summary', 'Summary of part 1', { b: 'Every result here comes from the **parallel sides**: co-interior and alternate angles, then congruent triangles.', v: sum1T, n: 'Here is the summary of part one. In a parallelogram the opposite sides are equal and parallel, the opposite angles are equal, and neighbouring angles add to one hundred eighty degrees. One equal and parallel pair is enough to make a parallelogram. The diagonals bisect each other, and each diagonal cuts the parallelogram into two congruent triangles. Part two looks at special parallelograms.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Proof (3 marks):** the parallel lines and the angle relation 1 + the congruence or sum 1 + the conclusion 1', '**Angles:** give the reason: opposite, co-interior or alternate', '**Algebra:** form the equation from the **equal** pair, then check', '**Mistake:** $\\angle A = \\angle B$ for neighbours; they add up to $180^\\circ$', '**Mistake:** claiming the diagonals are equal'], v: tips1T, n: 'Here is how marks are awarded. A three mark proof gives one mark for the parallel lines and the angle relation, one for the congruence or the angle sum, and one for the conclusion. Always write the reason beside each step. For algebra, form the equation from the pair that is equal, then check your answer. The two common mistakes are treating neighbouring angles as equal, and claiming the diagonals are equal.' }),
  ],
});

